<script lang="ts">
 import {untrack} from 'svelte';
 import type {ToolState} from '../../types';
 import Result from '../../components/Result.svelte';
 let {state=$bindable()}=$props<{state:ToolState}>();
 import {onDestroy} from 'svelte';import {workerTask} from '../../worker-task';import Worker from './file.worker?worker';import {download} from '../../browser-files';let busy=$state(false),error=$state('');const controller=new AbortController();onDestroy(()=>controller.abort());untrack(()=>{state.output??=null;state.name??='';state.report??='';});async function select(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;state.output=null;state.report='';busy=true;error='';try{if(file.size>10*1024*1024)throw new Error('10MB以内の画像を選択してください。');const result=await workerTask<{bytes:Uint8Array;type:string;extension:string;removed:number}>(new Worker(),new Uint8Array(await file.arrayBuffer()),controller.signal);const blob=new Blob([result.bytes as BlobPart],{type:result.type});const bitmap=await createImageBitmap(blob);try{if(!bitmap.width||bitmap.width*bitmap.height>40000000)throw new Error('画像は4,000万画素以内です。');}finally{bitmap.close();}state.output=blob;state.name='clean.'+result.extension;state.report=`メタデータ領域 ${result.removed}個を除去。再デコード確認済み（${blob.size}バイト）。`;}catch(e){error=(e as Error).message;}finally{busy=false;(e.target as HTMLInputElement).value='';}}
 
</script>
<label>JPEG / PNG / WebP画像<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onchange={select}/></label>{#if busy}<p role="status">メタデータを検証・削除中…</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<p role="status">{state.report}</p><button disabled={!state.output||busy} onclick={()=>download(state.output,state.name)}>処理済み画像を保存</button><p class="tool-note">例：スマートフォンのJPEGを選択し、位置情報等を削除して保存。10MB・4,000万画素まで。JPEGのAPP/COM、PNGの描画に不要な付随チャンク、WebPのEXIF/XMP/ICC等を除去。再エンコード・形式変更はしませんが、色プロファイル削除で色が変わる場合があります。アニメーション・CMYK JPEG・未対応構造・破損ファイルは拒否。画像に写った個人情報、透かし、ステガノグラフィは除去しません。</p>
